def _load_egi_names() -> tuple:
    """Load EGI name lookup from egi_names.json if available, else return fallback dict.
    Returns (lookup_dict, found_json: bool).
    """
    import pathlib, json as _json
    _here = pathlib.Path(__file__).parent
    _candidates = [
        _here / "egi_names.json",
        pathlib.Path("egi_names.json"),
    ]
    for _p in _candidates:
        try:
            if _p.exists():
                with open(_p, "r", encoding="utf-8") as _f:
                    _data = _json.load(_f)
                if isinstance(_data, dict) and "lookup" in _data:
                    return _data["lookup"], True
                return _data, True
        except Exception:
            pass
    return _EGI_LOOKUP_FALLBACK, False

EGI_NAME_LOOKUP, _EGI_JSON_FOUND = _load_egi_names()


def extract_learning_hub_id(filename: str) -> str:
    """Extract the Learning Hub Item ID (e.g. SUP_EDE_00012366 or SUP_EDE_00012366_001) from a filename."""
    m = re.search(r'([A-Z]{2,}_[A-Z]{2,}_\d+(?:_\d+)*)', filename, re.IGNORECASE)
    return m.group(1).upper() if m else ""

