# Compiled regex for inline free-text redaction:
# matches 1–3 consecutive Title-Case alphabetic words of 3–20 chars each.
_NAME_RE = re.compile(
    r'\b([A-Z][a-zA-Z]{2,19})(?:\s+([A-Z][a-zA-Z]{2,19})){0,2}\b'
)

# Separate pattern for honorific + surname (handles short surnames like Xu, Li, Wu, Yu).
# Matches: Mr. Xu  |  Mrs. Li  |  Dr. Wang Ming  |  Prof. Ng  |  Ms. Yu  |  Sir Ian
_HONORIFIC_RE = re.compile(
    r'\b(Mr|Mrs|Ms|Dr|Prof|Sir)\.?\s+([A-Z][a-zA-Z]{1,19})(?:\s+([A-Z][a-zA-Z]{1,19}))?\b'
)

# Pattern: a Title-Case word (likely a person's name) that starts a clause and is
# followed — within the same sentence — by an instructor-evaluation keyword.
# Catches: "Syrus is one of the best instructors", "Maria was an excellent trainer", etc.
# The lookahead stops at sentence boundaries (.!?) so it will not span two sentences.
_LEAD_PERSON_RE = re.compile(
    r'\b([A-Z][a-zA-Z]{2,19})\b'
    r'(?=[ \t]+(?:is|was|has|did|will|would|can|could)\b'
    r'[^.!?\n]{0,200}'
    r'(?:instructor|trainer|facilitator|presenter|teacher|coaching|'
    r'explains?|explained|teaching|lectures?|instructing))',
    re.IGNORECASE,
)

# Pattern: "Thank you to Name", "Thanks Name", "Thank you Name Surname", etc.
# Catches names that follow gratitude expressions — common vector for leaking names.
_THANK_RE = re.compile(
    r'\b[Tt]hank(?:s|ing)?\s+(?:you\s+)?(?:to\s+)?'
    r'([A-Z][a-zA-Z]{2,19}(?:\s+[A-Z][a-zA-Z]{2,19})?)\b'
)


def _looks_like_name(text: str) -> bool:
    """
    Return True if *text* (a complete answer string) looks like a person name.
    Accepts 1–4 capitalised alphabetic words where none are in _NON_NAME_VOCAB.
    Single-word names (e.g. "Bryan") are now included.
    """
    parts = str(text).strip().split()
    if not (1 <= len(parts) <= 4):
        return False
    for p in parts:
        clean = p.replace("-", "").replace("'", "")
        if not (len(clean) >= 2 and clean[0].isupper() and clean.isalpha()):
            return False
        if p.lower() in _NON_NAME_VOCAB:
            return False
    return True


def _is_name_question(answers: list) -> bool:
    """True if the majority of distinct answers look like whole person names."""
    if len(answers) < 2:
        return False
    n_names = sum(1 for a in answers if _looks_like_name(str(a)))
    return n_names >= max(2, len(answers) * 0.6)


def _is_freetext_question(grp: pd.DataFrame) -> bool:
    """
    Return True if a question group looks like a free-text field.

    Key signal: in free-text questions each participant writes a unique response,
    so almost every row has Count == 1.  Multiple-choice questions always have
    Count >> 1 per row (many respondents chose the same option).

    Secondary signal: extremely long average answer length (> 60 chars) that
    cannot plausibly be a pre-defined option.
    """
    n_rows         = len(grp)
    count_one_frac = (grp["Count"] == 1).sum() / max(n_rows, 1)
    unique         = grp["Answer"].nunique()
    avg_len        = grp["Answer"].str.len().mean()

    is_mostly_unique = (count_one_frac > 0.70) and (unique > 2)
    is_very_long     = avg_len > 60
    return is_mostly_unique or is_very_long


def _redact_names_in_text(text: str, known_names: frozenset = frozenset()) -> tuple:
    """
    Conservative free-text redaction — avoids false positives on product /
    solution / system names.

    Only two signals are used (in order):
    1. Honorific + surname  (Mr. Smith, Dr. Li, Prof. Wang Ming, etc.)
       — reliable indicator of a real person name.
    2. Known instructor names extracted from Pass-1 name questions
       — redact the exact words that appeared as whole-answer names upstream.

    The general Title-Case regex (_NAME_RE) is intentionally NOT applied to
    free text because it is too broad and would match SAP product names,
    solution names, module names, etc.

    Returns (redacted_text, was_changed).
    """
    def _replace_honorific(m: re.Match) -> str:
        surname = m.group(2)
        if surname.lower() not in _NON_NAME_VOCAB:
            return "[Name]"
        return m.group(0)

    new_text = _HONORIFIC_RE.sub(_replace_honorific, text)

    # Redact names in "Thank you to Name" / "Thanks Name" / "Thank you Name Surname" patterns.
    def _replace_thank(m: re.Match) -> str:
        name = m.group(1)
        if name.lower() not in _NON_NAME_VOCAB:
            return m.group(0).replace(name, "[Name]")
        return m.group(0)
    new_text = _THANK_RE.sub(_replace_thank, new_text)

    # Redact names in sentences like "Syrus is one of the best instructors."
    # Only fires when the same sentence contains an instructor-evaluation keyword.
    def _replace_lead(m: re.Match) -> str:
        word = m.group(1)
        if word.lower() not in _NON_NAME_VOCAB:
            return "[Name]"
        return m.group(0)
    new_text = _LEAD_PERSON_RE.sub(_replace_lead, new_text)

    # Redact known instructor/person names (longest first to avoid partial overlap)
    for _kn in sorted(known_names, key=len, reverse=True):
        if len(_kn) >= 3:
            new_text = re.sub(
                r'(?<!\w)' + re.escape(_kn) + r'(?!\w)',
                "[Name]", new_text, flags=re.IGNORECASE
            )

    return new_text, (new_text != text)


def anonymize_tidy(tidy: pd.DataFrame) -> tuple:
    """
    Two-pass anonymisation:

    Pass 1 — Name questions: questions whose entire answer set looks like a
    list of person names (e.g. "Instructor Name").  Every name-like answer is
    replaced with [Name] and counts are aggregated.  Individual name words are
    collected into *known_names* for use in Pass 2.

    Pass 2 — Free-text questions: ONLY honorific patterns (Mr./Dr./Prof. etc.)
    and known instructor names (from Pass 1) are redacted.  The general
    Title-Case regex is NOT applied so that product names, solution names and
    system names are preserved.

    Returns (anonymized_tidy, list_of_affected_question_texts).
    """
    tidy     = tidy.copy()
    affected = []
    known_names: set = set()   # instructor / person name words from Pass 1

    # ── Classify questions before any mutation ─────────────────────────────
    name_qs:     set = set()
    freetext_qs: set = set()
    for q, grp in tidy.groupby("Question"):
        answers = grp["Answer"].tolist()
        if _is_name_question(answers):
            name_qs.add(q)
        elif _is_freetext_question(grp):
            freetext_qs.add(q)

    # ── Pass 1: whole-answer name replacement ──────────────────────────────
    for q in name_qs:
        affected.append(q)
        grp = tidy[tidy["Question"] == q]
        for ans in grp["Answer"]:
            if _looks_like_name(str(ans)):
                for word in str(ans).strip().split():
                    clean = word.replace("-", "").replace("'", "")
                    if (len(clean) >= 3 and clean[0].isupper()
                            and clean.isalpha()
                            and word.lower() not in _NON_NAME_VOCAB):
                        known_names.add(word)   # collect for Pass 2
        mask = (tidy["Question"] == q) & tidy["Answer"].apply(
            lambda a: _looks_like_name(str(a))
        )
        tidy.loc[mask, "Answer"] = "[Name]"

    _known_frozen = frozenset(known_names)

    # ── Pass 2: conservative inline redaction for free-text ────────────────
    for q in freetext_qs:
        grp = tidy[tidy["Question"] == q]
        changed_any = False
        for idx in grp.index:
            original = str(tidy.at[idx, "Answer"])
            redacted, changed = _redact_names_in_text(original, _known_frozen)
            if changed:
                tidy.at[idx, "Answer"] = redacted
                changed_any = True
        if changed_any and q not in affected:
            affected.append(q)

    # ── Aggregate Pass-1 rows ───────────────────────────────────────────────
    if name_qs:
        group_cols = ["Class", "Poll", "Question", "Answer"]
        dates = tidy.groupby(group_cols, dropna=False)["Start Date"].first().reset_index()
        agg = (
            tidy.groupby(group_cols, dropna=False)
            .agg(Count=("Count", "sum"), Percentage=("Percentage", "sum"))
            .reset_index()
        )
        tidy = agg.merge(dates, on=group_cols, how="left")
        tidy = tidy[["Class", "Start Date", "Poll", "Question", "Answer", "Count", "Percentage"]]

    return tidy, affected


# ─────────────────────────────────────────────
# Helper functions — metrics
# ─────────────────────────────────────────────

def compute_zoom_metrics(tidy: pd.DataFrame, score_map: dict,
                         fav_threshold: int = 4,
                         unfav_threshold: int = 2) -> dict:
    per_question = {}
    for q, ans_map in score_map.items():
        q_data = tidy[tidy["Question"] == q]
        if q_data.empty:
            continue
        agg    = q_data.groupby("Answer")["Count"].sum().reset_index()
        total  = agg["Count"].sum()
        if total == 0:
            continue
        agg["Score"] = agg["Answer"].map(ans_map).fillna(3)
        agg["Pct"]   = (agg["Count"] / total * 100).round(1)

        mean_score = (agg["Score"] * agg["Count"]).sum() / total
        score_norm = round((mean_score - 1) / 4 * 100)

        fav_pct   = float(agg.loc[agg["Score"] >= fav_threshold,   "Pct"].sum())
        unfav_pct = float(agg.loc[agg["Score"] <= unfav_threshold, "Pct"].sum())
        neut_pct  = max(round(100 - fav_pct - unfav_pct), 0)
        top_ans   = agg.loc[agg["Count"].idxmax(), "Answer"]

        per_question[q] = {
            "mean"       : round(mean_score, 2),
            "score_norm" : score_norm,
            "fav_pct"    : round(fav_pct),
            "neut_pct"   : round(neut_pct),
            "unfav_pct"  : round(unfav_pct),
            "top_answer" : top_ans,
            "total"      : int(total),
        }

    if not per_question:
        return {}

    sorted_q    = sorted(per_question.items(), key=lambda x: x[1]["score_norm"], reverse=True)
    overall     = round(np.mean([v["score_norm"] for v in per_question.values()]))
    overall_fav = round(np.mean([v["fav_pct"]    for v in per_question.values()]))

    return {
        "per_question"    : per_question,
        "overall_score"   : overall,
        "overall_fav"     : overall_fav,
        "top_questions"   : sorted_q[:3],
        "bottom_questions": sorted_q[-3:],
    }


def compute_per_session_metrics(tidy: pd.DataFrame, score_map: dict) -> pd.DataFrame:
    """One row per Class × Poll with weighted mean score per question."""
    rows = []
    for (cls, poll), grp in tidy.groupby(["Class", "Poll"], sort=False):
        row = {"Class": cls, "Poll": poll}
        dates = grp["Start Date"].dropna()
        row["Session Date"] = dates.iloc[0].date() if not dates.empty else ""
        n_resp = grp.groupby("Question")["Count"].sum().max()
        row["Max Respondents"] = int(n_resp) if not pd.isna(n_resp) else 0

        for q, ans_map in score_map.items():
            q_data = grp[grp["Question"] == q]
            if q_data.empty:
                row[q[:60]] = None
                continue
            agg   = q_data.groupby("Answer")["Count"].sum().reset_index()
            total = agg["Count"].sum()
            if total == 0:
                row[q[:60]] = None
                continue
            agg["Score"] = agg["Answer"].map(ans_map).fillna(3)
            wmean = (agg["Score"] * agg["Count"]).sum() / total
            row[q[:60]] = round(wmean, 2)

        rows.append(row)
    return pd.DataFrame(rows)


def compute_per_session_dominant(tidy: pd.DataFrame) -> pd.DataFrame:
    """
    Start Poll variant of compute_per_session_metrics.
    Each question column shows the dominant answer and its percentage
    in the format  "Answer text (XX%)"  rather than a mean score.
    """
    rows = []
    for (cls, poll), grp in tidy.groupby(["Class", "Poll"], sort=False):
        row  = {"Class": cls, "Poll": poll}
        dates = grp["Start Date"].dropna()
        row["Session Date"]     = dates.iloc[0].date() if not dates.empty else ""
        n_resp                  = grp.groupby("Question")["Count"].sum().max()
        row["Max Respondents"]  = int(n_resp) if not pd.isna(n_resp) else 0

        for question, q_grp in grp.groupby("Question", sort=False):
            if _is_freetext_question(q_grp):
                continue
            agg   = q_grp.groupby("Answer")["Count"].sum().reset_index()
            total = int(agg["Count"].sum())
            if total == 0:
                row[question[:60]] = ""
                continue
            agg["pct"] = (agg["Count"] / total * 100).round(0)
            dom     = agg.loc[agg["pct"].idxmax()]
            dom_ans = str(dom["Answer"])
            dom_pct = int(dom["pct"])
            disp    = dom_ans[:32] + ("…" if len(dom_ans) > 32 else "")
            row[question[:60]] = f"{disp} ({dom_pct}%)"

        rows.append(row)
    return pd.DataFrame(rows)


def zoom_to_poll_wide(tidy: pd.DataFrame, score_map: dict) -> pd.DataFrame:
    """One row per Poll type — weighted mean score per question."""
    tidy = tidy.copy()

    def wmean(grp):
        scores = grp["Answer"].map(score_map.get(grp["Question"].iloc[0], {})).fillna(3)
        total  = grp["Count"].sum()
        return (scores * grp["Count"]).sum() / total if total > 0 else 3

    result = (
        tidy.groupby(["Poll", "Question"])
        .apply(lambda g: (
            g["Answer"].map(score_map.get(g["Question"].iloc[0], {})).fillna(3) * g["Count"]
        ).sum() / g["Count"].sum() if g["Count"].sum() > 0 else 3, include_groups=False)
        .reset_index()
        .rename(columns={0: "Score"})
    )
    wide = result.pivot_table(index="Poll", columns="Question", values="Score").reset_index()
    wide.columns.name = None
    return wide


# ─────────────────────────────────────────────
# Helper functions — charts
# ─────────────────────────────────────────────

def build_zoom_score_chart(per_question: dict) -> go.Figure:
    questions  = list(per_question.keys())
    scores     = [per_question[q]["score_norm"] for q in questions]
    totals     = [per_question[q]["total"]      for q in questions]
    fav_pcts   = [per_question[q]["fav_pct"]    for q in questions]
    wrapped_q  = [_wrap_label(q, 55) for q in questions]
    colors     = [SAP_BLUE if s >= 60 else SAP_HYPERLINK if s >= 40 else SAP_DARK_NAVY for s in scores]
    fig = go.Figure(go.Bar(
        x=scores, y=wrapped_q, orientation="h",
        marker_color=colors,
        text=[f"{s}%  (n={t})" for s, t in zip(scores, totals)],
        textposition="inside",
        insidetextanchor="end",
        constraintext="none",
        insidetextfont=dict(size=11, color=SAP_WHITE),
        outsidetextfont=dict(size=11, color=SAP_DARK_NAVY),
        customdata=list(zip(questions, totals, fav_pcts)),
        hovertemplate=(
            "<b>%{customdata[0]}</b><br>"
            "Score: <b>%{x:.0f}%</b><br>"
            "Respondents: <b>%{customdata[1]}</b><br>"
            "Positive: <b>%{customdata[2]}%</b>"
            "<extra></extra>"
        ),
    ))
    fig.update_layout(
        title=dict(text="Overall Score per Question (0–100%)", font=dict(color=SAP_DARK_NAVY, size=13)),
        xaxis=dict(range=[0, 100], ticksuffix="%", showgrid=False),
        yaxis=dict(autorange="reversed", tickfont=dict(size=12), showgrid=False),
        plot_bgcolor=SAP_WHITE, paper_bgcolor=SAP_WHITE,
        font=dict(family="Arial, sans-serif", color=SAP_BLACK),
        margin=dict(l=_chart_left_margin(wrapped_q), r=30, t=45, b=20),
        height=_chart_height(wrapped_q, min_row_px=60, extra_px=80),
        shapes=[dict(type="line", x0=60, x1=60, y0=-0.5, y1=len(questions)-0.5,
                     line=dict(color=SAP_GRAY_MED, width=1.5, dash="dot"),
                     xref="x", yref="y")],
        annotations=[dict(xref="x", x=60, y=-0.6, text="60% target", showarrow=False,
                          font=dict(size=9, color=SAP_GRAY_MED), xanchor="center")],
    )
    return fig


def build_zoom_favorable_chart(per_question: dict) -> go.Figure:
    q_keys     = list(per_question.keys())
    wrapped_q  = [_wrap_label(q, 55) for q in q_keys]
    fav_vals   = [per_question[q]["fav_pct"]   for q in q_keys]
    neut_vals  = [per_question[q]["neut_pct"]  for q in q_keys]
    unfav_vals = [per_question[q]["unfav_pct"] for q in q_keys]
    totals     = [per_question[q]["total"]     for q in q_keys]
    hover_fav   = [f"{q}<br>Positive: {f}%<br>Respondents: {t}"  for q, f, t in zip(q_keys, fav_vals,   totals)]
    hover_neut  = [f"{q}<br>Neutral: {n}%<br>Respondents: {t}"   for q, n, t in zip(q_keys, neut_vals,  totals)]
    hover_unfav = [f"{q}<br>Negative: {u}%<br>Respondents: {t}"  for q, u, t in zip(q_keys, unfav_vals, totals)]
    fig = go.Figure()
    fig.add_trace(go.Bar(
        name="Positive",  y=wrapped_q, x=fav_vals,   orientation="h",
        marker_color=SAP_BLUE,
        text=[f"{v:.0f}%" if v > 0 else "" for v in fav_vals],
        textposition="inside", insidetextanchor="middle",
        constraintext="none",
        textangle=0,
        textfont=dict(color=SAP_WHITE, size=10),
        hovertemplate="%{customdata}<extra></extra>",
        customdata=hover_fav,
    ))
    fig.add_trace(go.Bar(
        name="Neutral",   y=wrapped_q, x=neut_vals,  orientation="h",
        marker_color=SAP_LIGHT_BLUE,
        text=[f"{v:.0f}%" if v > 0 else "" for v in neut_vals],
        textposition="inside", insidetextanchor="middle",
        constraintext="none",
        textangle=0,
        textfont=dict(color=SAP_DEEP_NAVY, size=10),
        hovertemplate="%{customdata}<extra></extra>",
        customdata=hover_neut,
    ))
    fig.add_trace(go.Bar(
        name="Negative",  y=wrapped_q, x=unfav_vals, orientation="h",
        marker_color=SAP_DEEP_NAVY,
        text=[f"{v:.0f}%" if v > 0 else "" for v in unfav_vals],
        textposition="inside", insidetextanchor="middle",
        constraintext="none",
        textangle=0,
        textfont=dict(color=SAP_WHITE, size=10),
        hovertemplate="%{customdata}<extra></extra>",
        customdata=hover_unfav,
    ))
    fig.update_layout(
        barmode="stack",
        title=dict(text="Favorability by Question", font=dict(color=SAP_DARK_NAVY, size=13)),
        xaxis=dict(range=[0, 100], ticksuffix="%", showgrid=False),
        yaxis=dict(autorange="reversed", tickfont=dict(size=12), showgrid=False),
        plot_bgcolor=SAP_WHITE, paper_bgcolor=SAP_WHITE,
        legend=dict(
            orientation="h",
            yanchor="bottom", y=1.02,
            xanchor="left", x=0.0,
            font=dict(size=12), traceorder="normal",
        ),
        font=dict(family="Arial, sans-serif"),
        margin=dict(l=_chart_left_margin(wrapped_q), r=80, t=70, b=20),
        height=_chart_height(wrapped_q, min_row_px=60, extra_px=95),
    )
    for i, t in enumerate(totals):
        fig.add_annotation(
            xref="x", x=104,
            yref="y",  y=wrapped_q[i],
            text=f"n={t}",
            showarrow=False,
            font=dict(size=9, color=SAP_GRAY_DARK),
            xanchor="left", yanchor="middle",
        )
    return fig


def build_response_composition_chart(tidy: pd.DataFrame, score_map: dict) -> go.Figure:
    """100% stacked horizontal bar — one bar per question. Labels wrapped; full text on hover."""
    questions = list(score_map.keys())
    wrapped_q = [_wrap_label(q, 55) for q in questions]
    fig = go.Figure()
    for score in range(1, 6):
        x_vals      = []
        hover_texts = []
        for q in questions:
            q_data = tidy[tidy["Question"] == q]
            agg    = q_data.groupby("Answer")["Count"].sum().reset_index()
            total  = agg["Count"].sum()
            ans_at_score = [a for a, s in score_map[q].items() if s == score]
            pct    = 0.0
            labels = []
            for ans in ans_at_score:
                cnt = int(agg.loc[agg["Answer"] == ans, "Count"].sum())
                if total > 0:
                    p = cnt / total * 100
                    pct += p
                    labels.append(f"{ans[:25]}: {p:.0f}%")
            x_vals.append(round(pct))
            hover_texts.append("<br>".join(labels) if labels else f"(no responses at score {score})")
        fig.add_trace(go.Bar(
            name=SCORE_LABELS[score],
            y=wrapped_q, x=x_vals, orientation="h",
            marker_color=SCORE_COLORS[score],
            text=[f"{v:.0f}%" if v > 0 else "" for v in x_vals],
            textposition="inside",
            insidetextanchor="middle",
            constraintext="none",
            textfont=dict(color=SAP_WHITE if score in (1, 2, 5) else SAP_DEEP_NAVY, size=10),
            hovertemplate="<b>%{customdata[0]}</b><br><b>" + SCORE_LABELS[score] + "</b><br>%{customdata[1]}<extra></extra>",
            customdata=list(zip(questions, hover_texts)),
        ))
    fig.update_layout(
        barmode="stack",
        title=dict(text="Response Composition per Question  (left = negative → right = positive)",
                   font=dict(color=SAP_DARK_NAVY, size=13)),
        xaxis=dict(ticksuffix="%", range=[0, 100],
                   tickvals=[0, 25, 50, 75, 100], gridcolor=SAP_GRAY_LIGHT),
        yaxis=dict(autorange="reversed", tickfont=dict(size=12)),
        plot_bgcolor=SAP_WHITE, paper_bgcolor=SAP_WHITE,
        legend=dict(
            orientation="h", yanchor="bottom", y=1.02,
            xanchor="left", x=0.0,
            font=dict(size=10), traceorder="normal",
        ),
        font=dict(family="Arial, sans-serif"),
        margin=dict(l=_chart_left_margin(wrapped_q), r=30, t=80, b=10),
        height=_chart_height(wrapped_q, min_row_px=60, extra_px=95),
    )
    return fig


def _wrap_label(text: str, max_chars: int = 55) -> str:
    """
    Wrap text at word boundaries using <br> for Plotly y-axis labels.
    Default 32 chars/line — optimised for font-size 12 readability.
    """
    if len(text) <= max_chars:
        return text
    words = text.split()
    lines_out: list = []
    cur = ""
    for w in words:
        if cur and len(cur) + 1 + len(w) > max_chars:
            lines_out.append(cur)
            cur = w
        else:
            cur = (cur + " " + w).strip()
    if cur:
        lines_out.append(cur)
    return "<br>".join(lines_out)


def _chart_left_margin(wrapped_labels: list, px_per_char: float = 7.5, padding: int = 30) -> int:
    """
    Dynamic left margin sized for the longest single line across all wrapped labels.
    Uses 7.5 px/char for Arial 12 — the default Plotly y-axis tick font.
    Capped at 480 px to stay within a standard 700-px wide chart.
    """
    if not wrapped_labels:
        return 220
    max_line = max(max(len(line) for line in lbl.split("<br>")) for lbl in wrapped_labels)
    return max(180, min(480, int(max_line * px_per_char + padding)))


def _chart_height(wrapped_labels: list, px_per_line: int = 18,
                  min_row_px: int = 50, extra_px: int = 80) -> int:
    """
    Dynamic chart height that guarantees multi-line labels and bars never overlap.

    Per-question row height:
        max(min_row_px, extra_lines * px_per_line + min_row_px)
    where extra_lines = number of <br> tags (additional lines beyond the first).

    extra_px covers chart title (~32 px), x-axis ticks (~22 px), and
    padding (~26 px).  Add ~28 px more for a single legend row above the chart.

    Minimums:  280 px total so tiny datasets still render readably.
    """
    if not wrapped_labels:
        return 300
    total = sum(
        max(min_row_px, lbl.count("<br>") * px_per_line + min_row_px)
        for lbl in wrapped_labels
    )
    return max(280, total + extra_px)


def build_respondent_count_chart(tidy: pd.DataFrame) -> go.Figure:
    """Horizontal bar chart — respondent count per question."""
    q_counts = (
        tidy.groupby("Question")["Count"].sum()
        .reset_index()
        .rename(columns={"Count": "Respondents"})
    )
    q_order  = list(dict.fromkeys(tidy["Question"].tolist()))
    q_counts = q_counts.set_index("Question").reindex(q_order).reset_index()
    counts    = q_counts["Respondents"].tolist()
    max_count = max(counts) if counts else 1
    pct_vals   = [round(c / max_count * 100) for c in counts]
    bar_labels = [f"{p}%  (n={c})" for p, c in zip(pct_vals, counts)]
    raw_q      = q_counts["Question"].tolist()
    wrapped_q  = [_wrap_label(q, 55) for q in raw_q]
    fig = go.Figure(go.Bar(
        x=pct_vals, y=wrapped_q, orientation="h",
        marker_color=SAP_BLUE,
        text=bar_labels, textposition="inside",
        insidetextanchor="end",
        constraintext="none",
        textfont=dict(size=11, color=SAP_WHITE),
        hovertemplate="<b>%{customdata}</b><br>Response rate: <b>%{x}%</b><extra></extra>",
        customdata=raw_q,
    ))
    fig.update_layout(
        title=dict(text="Respondents per Question", font=dict(color=SAP_DARK_NAVY, size=13)),
        xaxis=dict(title="Response Rate", range=[0, 100],
                   ticksuffix="%", showgrid=False),
        yaxis=dict(autorange="reversed", tickfont=dict(size=12), showgrid=False),
        plot_bgcolor=SAP_WHITE, paper_bgcolor=SAP_WHITE,
        font=dict(family="Arial, sans-serif", color=SAP_BLACK),
        margin=dict(l=_chart_left_margin(wrapped_q), r=30, t=45, b=10),
        height=_chart_height(wrapped_q),
    )
    return fig
def _topic_label(question_text: str) -> str:
    """Return a short, readable topic label for a question string."""
    import re as _re
    q = question_text.lower()
    if any(kw in q for kw in ("satisf", "overall")):
        return "overall satisfaction"
    if any(kw in q for kw in ("valuable", "value")):
        return "perceived value"
    if any(kw in q for kw in ("implement", "apply", "likely")):
        return "implementation intent"
    if any(kw in q for kw in ("relevant", "relevance")):
        return "content relevance"
    if any(kw in q for kw in ("next step", "clear")):
        return "clarity of next steps"
    # Fallback: strip Q-number prefix, trim trailing punctuation, truncate
    stripped = _re.sub(r'^Q\d+\s*[-–:]\s*', '', question_text).strip().rstrip('?').strip()
    return stripped[:60] if stripped else question_text[:60]


# ─────────────────────────────────────────────
# Helper functions — PM insights
# ─────────────────────────────────────────────

def generate_zoom_insights(zm: dict, tidy: pd.DataFrame, score_map: dict) -> list:
    """Generate Portfolio Manager-level insights with priority and recommended actions."""
    insights    = []
    pq          = zm.get("per_question", {})
    if not pq:
        return insights

    overall     = zm.get("overall_score", 0)
    overall_fav = zm.get("overall_fav", 0)
    n_sessions  = tidy["Class"].nunique()
    poll_types  = tidy["Poll"].unique().tolist()
    n_polls     = len(poll_types)

    # ── 1. Overall session health ───────────────────────────────────
    if overall >= 70:
        health_label = "High Impact"
        ins_type = "strength"
        priority = "LOW"
        health_body = (
            "Participant feedback reflects strong overall satisfaction. The majority of individual "
            "responses fall in the positive category, indicating effective session delivery."
        )
        action = (
            "Continue the current delivery approach. Document the session structure as a best-practice "
            "reference for other facilitators and upcoming cohorts."
        )
    elif overall >= 50:
        health_label = "Developing"
        ins_type = "neutral"
        priority = "MEDIUM"
        health_body = (
            "Participant satisfaction is at a moderate level. While most responses are positive, "
            "a meaningful share of participants expressed neutral or mixed feedback, suggesting "
            "targeted improvements are warranted."
        )
        action = (
            "Schedule a portfolio review to discuss the lowest-scoring topics. "
            "Focus improvements on the questions with the weakest participant reception to achieve a meaningful uplift."
        )
    else:
        health_label = "Needs Attention"
        ins_type = "warning"
        priority = "HIGH"
        health_body = (
            "Participant feedback indicates this EGI needs significant attention. A substantial "
            "proportion of responses fall outside the positive category, highlighting structural "
            "issues in content or delivery."
        )
        action = (
            "Immediate escalation recommended. Consider a follow-up survey or structured debrief "
            "with participants to identify root causes. Review session design with the content team."
        )

    insights.append({
        "type": ins_type, "priority": priority,
        "title": f"Overall Delivery Quality — {health_label}",
        "text": health_body,
        "action": action,
    })

    # ── 2. Strongest topic area ────────────────────────────────────
    top = zm.get("top_questions", [])
    if top:
        top_q, top_v = top[0]
        top_label = _topic_label(top_q)
        insights.append({
            "type": "strength", "priority": "LOW",
            "title": "Highest Value Delivery Area",
            "text": (
                f"The <strong>{top_label}</strong> dimension consistently receives the highest "
                f"participant ratings across all sessions. The dominant participant response was "
                f"<em>\"{top_v['top_answer']}\"</em>, reflecting strong resonance with this content area."
            ),
            "action": (
                "Replicate the delivery approach for this topic across other sessions and cohorts. "
                "Use it as a reference model in facilitator calibration sessions."
            ),
        })

    # ── 3. Area requiring attention (v91 — score-tier-aware language) ─────────
    bottom = zm.get("bottom_questions", [])
    if bottom:
        bot_q, bot_v = bottom[0]
        bot_label = _topic_label(bot_q)

        if bot_v["score_norm"] >= 60:
            # All questions above target — show as a positive observation, not a warning
            insights.append({
                "type": "neutral", "priority": "LOW",
                "title": "Relative Improvement Opportunity",
                "text": (
                    f"All scored dimensions are performing above the satisfaction benchmark. "
                    f"The <strong>{bot_label}</strong> dimension shows the most room for further growth "
                    f"relative to other topics, though it already meets the performance benchmark."
                ),
                "action": (
                    "Continue monitoring this dimension in the next session cycle. "
                    "Minor delivery refinements may help narrow the gap with the highest-performing areas."
                ),
            })
        elif bot_v["score_norm"] >= 40:
            # Below target but not critical — mixed feedback, no mention of "negative"
            insights.append({
                "type": "warning", "priority": "MEDIUM",
                "title": "Priority Area for Improvement",
                "text": (
                    f"The <strong>{bot_label}</strong> dimension received mixed feedback, "
                    f"with a meaningful share of participants expressing neutral or less favourable "
                    f"responses. This is the primary area warranting content or delivery attention."
                ),
                "action": (
                    "Review the content for this dimension and consider supplementary material or an "
                    "updated exercise format. Track this area in the next session cycle for trend "
                    "confirmation."
                ),
            })
        else:
            # Genuinely low scores — strong warning warranted
            insights.append({
                "type": "warning", "priority": "HIGH",
                "title": "Priority Area for Improvement",
                "text": (
                    f"The <strong>{bot_label}</strong> dimension received consistently low ratings, with a "
                    f"significant proportion of participants expressing dissatisfaction. This represents a "
                    f"structural concern that should be escalated for immediate review."
                ),
                "action": (
                    "Redesign the session segment or content addressing this dimension in consultation "
                    "with subject matter experts. The depth of negative feedback indicates a structural "
                    "issue that will not self-correct. Add to the next governance review agenda."
                ),
            })

    # ── 4. Poll-type performance gap ───────────────────────────────
    if n_polls > 1:
        poll_scores = {}
        for poll_name in poll_types:
            pt = tidy[tidy["Poll"] == poll_name]
            sm = build_score_map(pt)
            zm_p = compute_zoom_metrics(pt, sm)
            if zm_p:
                poll_scores[poll_name] = zm_p.get("overall_score", 0)

        if len(poll_scores) > 1:
            best_poll  = max(poll_scores, key=poll_scores.get)
            worst_poll = min(poll_scores, key=poll_scores.get)
            gap        = round(poll_scores[best_poll] - poll_scores[worst_poll], 1)

            if gap >= 15:
                insights.append({
                    "type": "neutral", "priority": "MEDIUM",
                    "title": "Performance Gap Between Poll Types",
                    "text": (
                        f"<strong>{best_poll[:45]}</strong> substantially outperforms "
                        f"<strong>{worst_poll[:45]}</strong>. The gap is wide enough to suggest "
                        f"that participant experience differs meaningfully depending on when or how "
                        f"the poll was administered."
                    ),
                    "action": (
                        "Investigate whether the gap reflects differences in content difficulty, "
                        "participant expectations, or survey design. Consider aligning question "
                        "depth and framing across all poll types in the next content review."
                    ),
                })
            else:
                insights.append({
                    "type": "strength", "priority": "LOW",
                    "title": "Consistent Value Delivery Across Poll Types",
                    "text": (
                        f"All {n_polls} poll types show closely aligned performance levels, "
                        f"indicating consistent session quality regardless of the measurement point "
                        f"(start vs. closing vs. mid-session)."
                    ),
                    "action": "Maintain the current session structure. No corrective action needed for poll-type balance.",
                })

    # ── 5. Questions with low positive rate ──────────────────────
    low_fav_qs = [(q, v) for q, v in pq.items() if v["fav_pct"] < 40]
    if low_fav_qs:
        n_low      = len(low_fav_qs)
        ex_labels  = " and ".join([f"<em>{_topic_label(q)}</em>" for q, _ in low_fav_qs[:2]])
        prio_low   = "HIGH" if n_low >= 3 else "MEDIUM"
        insights.append({
            "type": "warning", "priority": prio_low,
            "title": "Key Dimensions Below Satisfaction Threshold",
            "text": (
                f"Several dimensions received a comparatively low share of positive responses, "
                f"including {ex_labels}. "
                f"These represent the most significant improvement opportunities in the current dataset."
            ),
            "action": (
                "Add these dimensions to the portfolio governance review agenda. Set a measurable "
                "improvement target for the next two session cycles and track progress systematically."
            ),
        })

    # ── 6. High neutral / undecided rate ──────────────────────────
    high_neutral_qs = [(q, v) for q, v in pq.items() if v["neut_pct"] > 30]
    if high_neutral_qs:
        q_n, v_n = high_neutral_qs[0]
        topic_n = _topic_label(q_n)
        insights.append({
            "type": "neutral", "priority": "MEDIUM",
            "title": "High Neutral Rate — Potential Hidden Concern",
            "text": (
                f"The <strong>{topic_n}</strong> dimension shows a notably high proportion of neutral responses. "
                f"A high neutral rate can mask underlying dissatisfaction "
                f"and should not be interpreted as satisfaction."
            ),
            "action": (
                "Provide clearer context for this dimension in the next session. Consider adding a "
                "follow-up open-text field to surface qualitative feedback. A high neutral rate "
                "warrants qualitative investigation to understand participant ambiguity."
            ),
        })

    # ── 7. Session-level variation ─────────────────────────────────
    if n_sessions >= 3:
        # Compute per-session overall score
        sess_scores = {}
        for cls, grp in tidy.groupby("Class"):
            sm   = build_score_map(grp)
            zm_s = compute_zoom_metrics(grp, sm)
            if zm_s:
                sess_scores[str(cls)] = zm_s.get("overall_score", 0)

        if len(sess_scores) >= 2:
            max_cls   = max(sess_scores, key=sess_scores.get)
            min_cls   = min(sess_scores, key=sess_scores.get)
            range_gap = round(sess_scores[max_cls] - sess_scores[min_cls], 1)

            if range_gap >= 20:
                insights.append({
                    "type": "neutral", "priority": "MEDIUM",
                    "title": "Notable Variation in Session Performance",
                    "text": (
                        "The highest-performing session in this dataset stands notably above the "
                        "lowest-performing one. This gap suggests inconsistent delivery quality "
                        "across facilitators or cohorts."
                    ),
                    "action": (
                        "Identify the highest-performing session and interview its facilitator(s) "
                        "to extract best practices. Review the delivery notes for the session with "
                        "the weakest results to understand what differed. Consider a facilitator "
                        "calibration exercise before the next cohort."
                    ),
                })

    # ── 8. Customer Value Signal — interprets Q02, Q03, Q04 as business value ──
    # Find the "How Valuable", "Likely to Implement", and "How Relevant" questions
    _VALUE_KWS   = ("valuable", "value")
    _RELEVANT_KWS = ("relevant", "relevance")
    _IMPLEMENT_KWS = ("implement", "apply", "likely")

    val_qs   = {q: v for q, v in pq.items()
                if any(kw in q.lower() for kw in _VALUE_KWS)}
    rel_qs   = {q: v for q, v in pq.items()
                if any(kw in q.lower() for kw in _RELEVANT_KWS)}
    impl_qs  = {q: v for q, v in pq.items()
                if any(kw in q.lower() for kw in _IMPLEMENT_KWS)}

    if val_qs or rel_qs or impl_qs:
        # Aggregate positive rates for each dimension
        val_fav  = round(np.mean([v["fav_pct"] for v in val_qs.values()]))  if val_qs  else None
        rel_fav  = round(np.mean([v["fav_pct"] for v in rel_qs.values()]))  if rel_qs  else None
        impl_fav = round(np.mean([v["fav_pct"] for v in impl_qs.values()])) if impl_qs else None

        # Build a narrative sentence for each available dimension
        signals = []
        if val_fav is not None:
            if val_fav >= 70:
                signals.append(
                    "Participants consistently rated this EGI as <em>Valuable</em> or "
                    "<em>Very Valuable</em>, indicating strong perceived business benefit "
                    "and clear return on their investment of time."
                )
            elif val_fav >= 50:
                signals.append(
                    "The majority of participants rated this EGI as <em>Valuable</em> or "
                    "<em>Very Valuable</em>, though a meaningful share expressed moderate views — "
                    "consider enriching the content with more concrete, role-specific use cases "
                    "to strengthen this signal."
                )
            else:
                signals.append(
                    "Fewer than half of participants rated this EGI as <em>Valuable</em> or "
                    "<em>Very Valuable</em>. This is a low customer value signal that warrants "
                    "a content review to ensure the material addresses real customer challenges."
                )

        if rel_fav is not None:
            if rel_fav >= 70:
                signals.append(
                    "Most participants found the content <em>Relevant</em> or "
                    "<em>Extremely Relevant</em> to their role, indicating strong alignment "
                    "between the EGI scope and participant responsibilities."
                )
            elif rel_fav >= 50:
                signals.append(
                    "A majority of participants found the content relevant to their role, "
                    "though some may not have seen a direct connection to their day-to-day "
                    "work — adding industry- or role-specific examples could improve this."
                )
            else:
                signals.append(
                    "Fewer than half of participants found the content directly relevant to "
                    "their role. The audience composition or content framing should be reviewed "
                    "to improve the fit between the EGI material and participant needs."
                )

        if impl_fav is not None:
            if impl_fav >= 70:
                signals.append(
                    "The majority of participants expressed a <em>Likely</em> or "
                    "<em>Very Likely</em> intent to implement what they learned — "
                    "a strong indicator of actionable, customer-facing impact."
                )
            elif impl_fav >= 50:
                signals.append(
                    "More than half of participants are likely to implement the learnings, "
                    "though the remaining group may benefit from a follow-up resource pack "
                    "or a guided next-step document to convert intent into action."
                )
            else:
                signals.append(
                    "Fewer than half of participants indicated they are likely to implement "
                    "what they learned. This is a low activation signal — consider adding a "
                    "structured \"what to do next\" step within the EGI to bridge the "
                    "knowledge-action gap."
                )

        # Overall value tier
        all_rates = [r for r in [val_fav, rel_fav, impl_fav] if r is not None]
        avg_value = round(np.mean(all_rates), 1) if all_rates else 0

        if avg_value >= 70:
            v_type, v_priority, v_tier = "strength", "LOW",    "High Impact"
        elif avg_value >= 50:
            v_type, v_priority, v_tier = "neutral",  "MEDIUM", "Building"
        else:
            v_type, v_priority, v_tier = "warning",  "HIGH",   "Needs Attention"

        body_parts = " ".join(signals) if signals else (
            "No questions mapped to the Value / Relevance / Implementation dimensions were found."
        )

        insights.append({
            "type": v_type,
            "priority": v_priority,
            "title": f"Customer Value Signal — {v_tier}",
            "text": body_parts,
            "action": (
                "Use these value indicators in executive briefings and portfolio reviews as evidence "
                "of the EGI's customer impact. Dimensions with below-majority positive rates should "
                "be addressed in the next content revision cycle to strengthen the customer value proposition."
            ),
        })

    return insights


def render_insight(ins: dict):
    ptype  = ins.get("priority", "LOW")
    itype  = ins.get("type", "neutral")
    title  = ins.get("title", "")
    text   = ins.get("text", "")
    action = ins.get("action", "")

    # ── Colours per card type (all inline — avoids Streamlit markdown class issues)
    _border_clr = SAP_BLUE      if itype == "strength" else (SAP_DEEP_NAVY if itype == "warning" else SAP_GRAY_MED)
    _bg_clr     = SAP_LIGHT_SKY if itype in ("strength", "warning")        else SAP_GRAY_LIGHT

    # ── Badge: pre-computed as a plain string — NO ternary inside the f-string
    if ptype == "HIGH":
        _badge = (
            f'<span style="background:{SAP_DEEP_NAVY};color:{SAP_WHITE};' +
            'font-size:0.63rem;font-weight:700;padding:2px 8px;border-radius:10px;' +
            f'letter-spacing:0.06em;margin-right:6px;">URGENT</span>'
        )
    elif ptype == "MEDIUM":
        _badge = (
            f'<span style="background:{SAP_DARK_NAVY};color:{SAP_WHITE};' +
            'font-size:0.63rem;font-weight:700;padding:2px 8px;border-radius:10px;' +
            f'letter-spacing:0.06em;margin-right:6px;">MONITOR</span>'
        )
    else:
        _badge = ""

    # ── Single-line HTML string — no blank lines inside divs
    _html = (
        f'<div style="border-left:4px solid {_border_clr};background:{_bg_clr};' +
        'border-radius:6px;padding:12px 16px;margin-bottom:10px;">' +
        f'<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;">' +
        _badge +
        f'<span style="font-weight:700;font-size:0.88rem;color:{SAP_DEEP_NAVY};">{title}</span>' +
        '</div>' +
        f'<div style="font-size:0.82rem;color:{SAP_GRAY_DARK};margin-bottom:8px;line-height:1.5;">{text}</div>' +
        f'<div style="font-size:0.82rem;color:{SAP_BLACK};' +
        f'border-top:1px solid {SAP_GRAY_LIGHT};padding-top:6px;line-height:1.5;">' +
        f'<span style="color:{SAP_BLUE};font-weight:700;">→</span> ' +
        f'<strong>Next step:</strong> {action}</div></div>'
    )
    st.markdown(_html, unsafe_allow_html=True)


def _plain_first_sentence(html_str: str, max_chars: int = 130) -> str:
    """Strip HTML tags, return first sentence capped at max_chars."""
    plain = re.sub(r'<[^>]+>', '', html_str).strip()
    m = re.search(r'\.(?:\s|$)', plain)
    plain = plain[:m.end()].rstrip() if m else plain
    if len(plain) > max_chars:
        plain = plain[:max_chars].rstrip() + '\u2026'
    return plain


def _strip_html(html_str: str) -> str:
    """Strip HTML tags, returning plain untruncated text."""
    return re.sub(r'<[^>]+>', '', html_str).strip()


def group_insights(insights: list) -> dict:
    """Split insights into two management-friendly categories.

    Categories:
      Value & Impact  — type == 'strength', OR type == 'neutral' with LOW priority
      Recommendations — type == 'warning',  OR type == 'neutral' with HIGH/MEDIUM priority
    """
    groups: dict = {"Value & Impact": [], "Recommendations": []}
    for ins in insights:
        t = ins.get("type",     "neutral")
        p = ins.get("priority", "LOW")
        if t == "strength" or (t == "neutral" and p == "LOW"):
            groups["Value & Impact"].append(ins)
        else:
            groups["Recommendations"].append(ins)
    return groups


# ─────────────────────────────────────────────
# Helper functions — export
# ─────────────────────────────────────────────

def export_zoom_excel(tidy: pd.DataFrame, zm: dict, score_map: dict) -> bytes:
    output = BytesIO()

    # ── Single master session mapping — date descending, used by ALL sheets ──
    _sess_order = (
        tidy.groupby("Class")["Start Date"].min()
        .reset_index()
        .sort_values("Start Date", ascending=False, na_position="last")
    )
    _master_cm = {c: f"Session {i+1}" for i, c in enumerate(_sess_order["Class"])}

    with pd.ExcelWriter(output, engine="openpyxl") as writer:

        # Sheet 1 — Raw Data (Class anonymised with master mapping)
        _tx = tidy.copy()
        _tx["Class"] = _tx["Class"].map(_master_cm)
        _tx = _tx.rename(columns={"Class": "Session"})
        # Sort rows so Session 1 appears first (matches Per Session Summary order)
        _sk_raw = {f"Session {i+1}": i for i in range(len(_master_cm))}
        _tx["_sk"] = _tx["Session"].map(_sk_raw)
        _tx = _tx.sort_values("_sk").drop(columns=["_sk"]).reset_index(drop=True)
        if "Start Date" in _tx.columns:
            _tx["Start Date"] = _tx["Start Date"].apply(
                lambda d: d.strftime("%Y-%m") if hasattr(d, "strftime") and pd.notna(d) else "")
        _tx.to_excel(writer, sheet_name="Raw Data", index=False)

        # Sheet 2 — Per Session Summary (anonymised + YYYY-MM + sorted Q cols)
        df_session = compute_per_session_metrics(tidy, score_map)
        # Sort rows using same key as display table (min Start Date per class, desc)
        _sk_ex = {c: i for i, c in enumerate(_sess_order["Class"])}
        df_session["_sk"] = df_session["Class"].map(_sk_ex)
        df_session = df_session.sort_values("_sk").drop(columns=["_sk"]).reset_index(drop=True)
        df_session["Class"] = df_session["Class"].map(_master_cm)
        df_session = df_session.rename(columns={"Class":"Session"})
        if "Session Date" in df_session.columns:
            df_session["Session Date"] = df_session["Session Date"].apply(
                lambda d: d.strftime("%Y-%m") if hasattr(d,"strftime") and str(d) not in ("","NaT") else "")
            df_session = df_session.rename(columns={"Session Date":"Date"})
        _fcp = [c for c in df_session.columns if c in ("Session","Poll","Date","Max Respondents")]
        _qcp = sorted([c for c in df_session.columns if c not in _fcp],
                      key=lambda c: int(m.group(1)) if (m := re.search(r'Q(\d+)', c, re.I)) else 999)
        df_session = df_session[_fcp + _qcp]
        df_session.to_excel(writer, sheet_name="Per Session Summary", index=False)

        # Sheet 3 — per-question metrics (aggregated)
        rows = []
        for q, v in zm.get("per_question", {}).items():
            rows.append({
                "Question"           : q,
                "Total Responses"    : v["total"],
                "Mean Score (1–5)"   : v["mean"],
                "Score (0–100%)"     : v["score_norm"],
                "Positive %"        : v["fav_pct"],
                "Neutral %"          : v["neut_pct"],
                "Negative %"      : v["unfav_pct"],
                "Most Common Answer" : v["top_answer"],
            })
        pd.DataFrame(rows).to_excel(writer, sheet_name="Question Metrics", index=False)

        # Sheet 4 — poll type summary
        poll_rows = []
        for poll_name in tidy["Poll"].unique():
            pt   = tidy[tidy["Poll"] == poll_name]
            sm   = build_score_map(pt)
            zm_p = compute_zoom_metrics(pt, sm)
            if zm_p:
                n_cls = pt["Class"].nunique()
                poll_rows.append({
                    "Poll Type"         : poll_name,
                    "Sessions"          : n_cls,
                    "Questions"         : len(zm_p.get("per_question", {})),
                    "Overall Score (%)" : zm_p.get("overall_score", ""),
                    "Positive %"       : zm_p.get("overall_fav", ""),
                })
        pd.DataFrame(poll_rows).to_excel(writer, sheet_name="Poll Type Summary", index=False)

        # Sheet 5 — KPI summary
        kpi_rows = [
            {"KPI": "Sessions Analyzed",       "Value": tidy["Class"].nunique()},
            {"KPI": "Poll Types",               "Value": tidy["Poll"].nunique()},
            {"KPI": "Questions Analyzed",       "Value": len(zm.get("per_question", {}))},
            {"KPI": "Overall Score (0–100%)",   "Value": f"{zm.get('overall_score', 'N/A')}%"},
            {"KPI": "Overall Positive %",      "Value": f"{zm.get('overall_fav', 'N/A')}%"},
        ]
        pd.DataFrame(kpi_rows).to_excel(writer, sheet_name="KPI Summary", index=False)

    return output.getvalue()


# ─────────────────────────────────────────────
# Helper functions — PPTX export
# ─────────────────────────────────────────────


def generate_pptx_bytes(tidy: pd.DataFrame, zm: dict, score_map: dict,
                        source_filename: str = "",
                        egi_name: str = "",
                        n_egis: int = 0) -> bytes:
    """
    3-slide SAP-branded PPTX for EGI Closing Poll:
      1 — Cover  (deep-navy, EGI name, key metrics panel, SAP logo)
      2 — Executive Summary  (KPI cards + key insights + session list)
      3 — Positive / Negative Breakdown  (full-width stacked bars)
    """
    from pptx import Presentation
    from pptx.util import Inches, Pt, Emu
    from pptx.dml.color import RGBColor
    from pptx.enum.text import PP_ALIGN
    import re as _re, io as _io, base64 as _b64

    # ── Colour palette ────────────────────────────────────────────
    C_DEEP_NAVY  = RGBColor(0x00, 0x14, 0x4A)
    C_DARK_NAVY  = RGBColor(0x00, 0x2A, 0x86)
    C_BLUE       = RGBColor(0x1B, 0x90, 0xFF)
    C_LIGHT_BLUE = RGBColor(0x89, 0xD1, 0xFF)
    C_LIGHT_SKY  = RGBColor(0xD1, 0xEF, 0xFF)
    C_WHITE      = RGBColor(0xFF, 0xFF, 0xFF)
    C_BLACK      = RGBColor(0x00, 0x00, 0x00)
    C_GRAY_DARK  = RGBColor(0x66, 0x66, 0x66)
    C_GRAY_MED   = RGBColor(0x99, 0x99, 0x99)
    C_GRAY_LIGHT = RGBColor(0xEA, 0xEC, 0xEE)
    # Soft blue-gray palette (v88 — no greens / lavender)
    _SOFT = [
        RGBColor(0xC0, 0xD8, 0xEE),   # #C0D8EE  Readiness
        RGBColor(0xC8, 0xE0, 0xEE),   # #C8E0EE  Intent & Timeline
        RGBColor(0xCC, 0xE8, 0xFA),   # #CCE8FA  Familiarity
        RGBColor(0xC8, 0xD8, 0xE8),   # #C8D8E8  Motivation
        RGBColor(0xD5, 0xE8, 0xF5),   # #D5E8F5  Awareness
        RGBColor(0xDC, 0xDF, 0xE4),   # #DCDFE4  Other / gray
    ]
    C_SOFT_ROW = RGBColor(0xD5, 0xE8, 0xF5)   # findings / table row background
    # Start Poll bar colours (mirrors _SP_BAR_COLORS in the web app)
    _SP_CLRS = [
        RGBColor(0x00, 0x70, 0xF2),
        RGBColor(0x1B, 0x90, 0xFF),
        RGBColor(0x5B, 0xB5, 0xFF),
        RGBColor(0x89, 0xD1, 0xFF),
        RGBColor(0x00, 0x2A, 0x86),
        RGBColor(0x00, 0x14, 0x4A),
        RGBColor(0x99, 0x99, 0x99),
    ]
    _SP_TXT = [C_WHITE, C_WHITE, C_WHITE, C_DEEP_NAVY, C_WHITE, C_WHITE, C_WHITE]

    # ── Presentation setup ────────────────────────────────────────
    prs = Presentation()
    prs.slide_width  = Inches(13.33)
    prs.slide_height = Inches(7.5)
    blank = prs.slide_layouts[6]

    # ── Poll-type detection ───────────────────────────────────────
    _closing = all(_is_closing_poll(p) for p in tidy["Poll"].unique())

    # ── Derived data ──────────────────────────────────────────────
    pq           = zm.get("per_question", {})
    overall      = zm.get("overall_score", 0)
    n_sess       = tidy["Class"].nunique()
    insights_all = generate_zoom_insights(zm, tidy, score_map)
    _grp         = group_insights(insights_all)

    resp_per_sess = (
        tidy.groupby(["Class", "Question"])["Count"]
        .sum().reset_index().groupby("Class")["Count"].max()
    )
    total_resp   = int(resp_per_sess.sum()) if not resp_per_sess.empty else 0
    avg_resp     = round(resp_per_sess.mean(), 1) if not resp_per_sess.empty else 0

    dates     = tidy["Start Date"].dropna()
    date_strs = sorted(set(d.strftime("%b %d, %Y") for d in dates if pd.notna(d)))
    date_disp = ", ".join(date_strs[:3]) if date_strs else "N/A"

    _egi_display = egi_name if egi_name else "SAP EGI Session"

    _q01_key = next((q for q in pq if _re.search(r"(satisf|overall|q01)", q, _re.I)), None)
    _q01_fav = round(pq[_q01_key]["fav_pct"]) if _q01_key else None
    _q03_key = next((q for q in pq if _re.search(r"(likely|implement|q03)", q, _re.I)), None)
    _q03_fav = round(pq[_q03_key]["fav_pct"]) if _q03_key else None

    # ── SAP logo (PNG from SVG) ────────────────────────────────────
    # SAP logo — embedded as base64, zero runtime dependencies
