# ─────────────────────────────────────────────
# Load and process all uploaded files
# ─────────────────────────────────────────────
zoom_files = {}   # {filename → {"tidy": df, "item_id": str, "anon_qs": list, "default_name": str}}
errors     = []

for f in uploaded_files:
    item_id      = extract_learning_hub_id(f.name)
    default_name = EGI_NAME_LOOKUP.get(item_id, item_id) if item_id else f.name
    egi_key      = f"egi_{f.name}"

    # Pre-initialise session-state with default name (only on first encounter)
    if egi_key not in st.session_state:
        st.session_state[egi_key] = default_name

    try:
        f.seek(0)
        df_raw   = pd.read_excel(f, header=None)
        f.seek(0)
        df_check = pd.read_excel(f, header=0)
    except Exception as e:
        errors.append(f"Could not read '{f.name}': {e}")
        continue

    if df_raw.empty:
        errors.append(f"'{f.name}' appears to be empty.")
        continue

    if is_zoom_polling_format(df_check):
        try:
            tidy_raw = parse_zoom_polling(df_check)
        except Exception as _parse_err:
            errors.append(
                f"'{f.name}' could not be parsed — unexpected format: {_parse_err}"
            )
            continue

        # ── Unnamed-poll guard ────────────────────────────────────────────
        # parse_zoom_polling already filters out rows whose poll name is blank
        # or invalid (_is_valid_poll).  If the result is empty it means every
        # poll in this file was unnamed — surface a clear message instead of
        # letting downstream code crash.
        if tidy_raw.empty:
            errors.append(
                f"'{f.name}' — all polls in this file are unnamed and have been "
                f"excluded from the analysis."
            )
            continue

        try:
            tidy, anon_qs = anonymize_tidy(tidy_raw)
        except Exception as _anon_err:
            errors.append(
                f"'{f.name}' could not be anonymised — {_anon_err}"
            )
            continue

        zoom_files[f.name] = {
            "tidy"        : tidy,
            "item_id"     : item_id,
            "anon_qs"     : anon_qs,
            "default_name": default_name,
        }
    else:
        errors.append(f"'{f.name}' is not a recognised Zoom Polling Report format.")

for err in errors:
    st.warning(err)

if not zoom_files:
    st.stop()

